INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ba1d6f3c-91a9-5b37-b150-ebb6ab7068f4', 'Panama Guide for the report and voluntary disclosure', 'Guide for the report and voluntary disclosure of environmental, social and corporate governance factors', 'The Panama Stock Exchange (BVP), together with IDB Invest, has promoted the development of this Guide with the intention of supporting companies in the development and implementation of their sustainability strategies and the subsequent communication of their environmental performance. , social and corporate governance. This Guide facilitates the growth of the sustainable finance market and promotes transparency on sustainability issues in the capital markets. This Guide seeks: (1) Support companies to simplify and standardize the process of developing sustainability strategies (2) Guide issuers in the process of preparing voluntary reports on the disclosure of ESG factors (3) Contribute to the implementation and dissemination of best practices and global standards in corporate sustainability, and encourage issuers to follow them.', 'The Panama Stock Exchange (BVP), together with IDB Invest, has promoted the development of this Guide with the intention of supporting companies in the development and implementation of their sustainability strategies and the subsequent communication of their environmental performance. , social and corporate governance. This Guide facilitates the growth of the sustainable finance market and promotes transparency on sustainability issues in the capital markets. This Guide seeks: (1) Support companies to simplify and standardize the process of developing sustainability strategies (2) Guide issuers in the process of preparing voluntary reports on the disclosure of ESG factors (3) Contribute to the implementation and dissemination of best practices and global standards in corporate sustainability, and encourage issuers to follow them.', 'The Panama Stock Exchange (BVP), together with IDB Invest, has promoted the development of this Guide with the intention of supporting companies in the development and implementation of their sustainability strategies and the subsequent communication of their environmental performance. , social and corporate governance. This Guide facilitates the growth of the sustainable finance market and promotes transparency on sustainability issues in the capital markets. This Guide seeks: (1) Support companies to simplify and standardize the process of developing sustainability strategies (2) Guide issuers in the process of preparing voluntary reports on the disclosure of ESG factors (3) Contribute to the implementation and dissemination of best practices and global standards in corporate sustainability, and encourage issuers to follow them.', 'Panama', 'climate', 'in_force', '2021-01-01'::date, 'Panama', 'https://www.carrotsandsticks.org/policies/140_1', ARRAY['regulations', 'sdg16', 'disclosure', 'voluntary', 'panama']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('830b4b2d-4214-5900-8659-5eed65642e1d', 'Panama Guide for the Preparation of a Career Plan', 'Guide for the Preparation of a Career Plan for People with Disabilities (PwD), with a Gender Perspective', 'This "Guide for the Preparation of a Career Plan for Persons with Disabilities (PwD), with a Gender Perspective", is framed in the respect and promotion of human rights, inclusion and diversity, through a strategy that allows us to go a step further in the labor inclusion of people with disabilities and encourage the creation of career plans for PwD, which consider a gender perspective.', 'This "Guide for the Preparation of a Career Plan for Persons with Disabilities (PwD), with a Gender Perspective", is framed in the respect and promotion of human rights, inclusion and diversity, through a strategy that allows us to go a step further in the labor inclusion of people with disabilities and encourage the creation of career plans for PwD, which consider a gender perspective.', 'This "Guide for the Preparation of a Career Plan for Persons with Disabilities (PwD), with a Gender Perspective", is framed in the respect and promotion of human rights, inclusion and diversity, through a strategy that allows us to go a step further in the labor inclusion of people with disabilities and encourage the creation of career plans for PwD, which consider a gender perspective.', 'Panama', 'social', 'in_force', '2021-01-01'::date, 'Panama', 'https://www.carrotsandsticks.org/policies/140_4', ARRAY['sdg10', 'mandatory', 'sdg5', 'sdg16', 'mandatory_regulations', 'disclosure', 'panama']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fd69f385-5b09-58a8-9d8c-2bce8d0bba38', 'Panama Corporate guide: Social License to operate', 'Corporate guide: Social License to operate', 'The Guide establishes the steps to take to have an optimal relationship with the communities in which companies operate. It establishes the need to maintain positive relationships with communities and provides methodology on how to do so. In addition, it recommends reporting to key stakeholders (external and internal) progress in community relations.', 'The Guide establishes the steps to take to have an optimal relationship with the communities in which companies operate. It establishes the need to maintain positive relationships with communities and provides methodology on how to do so. In addition, it recommends reporting to key stakeholders (external and internal) progress in community relations.', 'The Guide establishes the steps to take to have an optimal relationship with the communities in which companies operate. It establishes the need to maintain positive relationships with communities and provides methodology on how to do so. In addition, it recommends reporting to key stakeholders (external and internal) progress in community relations.', 'Panama', 'climate', 'in_force', '2016-01-01'::date, 'Panama', 'https://www.carrotsandsticks.org/policies/140_6', ARRAY['sdg11', 'mandatory', 'mandatory_regulations', 'disclosure', 'panama']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b012ed71-1cf0-5e51-b9e9-0ea58ae59e92', 'Panama Sector Guide. Challenges and opportunities for the sustainability', 'Sector Guide. Challenges and opportunities for the sustainability of the. Banking Sector', 'The Guide provides an analysis of the challenges and opportunities for the banking sector in the country, and emphasizes the importance of public and proactive disclosure of information management policies to stakeholders.', 'The Guide provides an analysis of the challenges and opportunities for the banking sector in the country, and emphasizes the importance of public and proactive disclosure of information management policies to stakeholders.', 'The Guide provides an analysis of the challenges and opportunities for the banking sector in the country, and emphasizes the importance of public and proactive disclosure of information management policies to stakeholders.', 'Panama', 'climate', 'in_force', '2015-01-01'::date, 'Panama', 'https://www.carrotsandsticks.org/policies/140_2', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'panama']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('202dc9e1-9cf9-54d7-9eb0-a3b0a131777a', 'Panama Sectoral Guide of the Construction Sector', 'Sectoral Guide of the Construction Sector', 'This document gathers the results of the work carried out by Sumarse, which aims to analyze the challenges and opportunities for the sustainability of key economic sectors for Panama.', 'This document gathers the results of the work carried out by Sumarse, which aims to analyze the challenges and opportunities for the sustainability of key economic sectors for Panama.', 'This document gathers the results of the work carried out by Sumarse, which aims to analyze the challenges and opportunities for the sustainability of key economic sectors for Panama.', 'Panama', 'climate', 'in_force', '2015-01-01'::date, 'Panama', 'https://www.carrotsandsticks.org/policies/140_7', ARRAY['sdg13', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure', 'panama']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0b7e69f3-83d9-5cc9-83b1-662ecc0aa1ba', 'Panama Responsible Communication Guide', 'Responsible Communication Guide', 'How the company communicates its commitments to society and its CSR actions and strategies has an impact on the organizational culture. This communication talks about how the company interprets the obligations and challenges posed by today.', 'How the company communicates its commitments to society and its CSR actions and strategies has an impact on the organizational culture. This communication talks about how the company interprets the obligations and challenges posed by today.', 'How the company communicates its commitments to society and its CSR actions and strategies has an impact on the organizational culture. This communication talks about how the company interprets the obligations and challenges posed by today.', 'Panama', 'governance', 'in_force', '2015-01-01'::date, 'Panama', 'https://www.carrotsandsticks.org/policies/140_8', ARRAY['panama', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c912ca17-b1b5-599a-80ae-8127b73a57fc', 'Panama Corporate Volunteer Guide', 'Corporate Volunteer Guide', 'This model includes all the necessary elements to guarantee that the volunteer program is voluntary, measurable and that it is aligned with the interests of the volunteers and the company''s CSR strategy.', 'This model includes all the necessary elements to guarantee that the volunteer program is voluntary, measurable and that it is aligned with the interests of the volunteers and the company''s CSR strategy.', 'This model includes all the necessary elements to guarantee that the volunteer program is voluntary, measurable and that it is aligned with the interests of the volunteers and the company''s CSR strategy.', 'Panama', 'governance', 'in_force', '2014-01-01'::date, 'Panama', 'https://www.carrotsandsticks.org/policies/140_5', ARRAY['panama', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('048b7073-97e6-5b02-a830-3c4971c9651f', 'Panama Law 42. That regulates the operations of financial', 'Law 42. That regulates the operations of financial companies', 'The Law regulates the activity of the financial companies. With regards to reporting, the Law states that within four months after the close of the fiscal year, financial companies must submit to the Financial Companies Department of the Ministry of Commerce and Industry their financial statements, duly audited by an authorized public accountant.', 'The Law regulates the activity of the financial companies. With regards to reporting, the Law states that within four months after the close of the fiscal year, financial companies must submit to the Financial Companies Department of the Ministry of Commerce and Industry their financial statements, duly audited by an authorized public accountant.', 'The Law regulates the activity of the financial companies. With regards to reporting, the Law states that within four months after the close of the fiscal year, financial companies must submit to the Financial Companies Department of the Ministry of Commerce and Industry their financial statements, duly audited by an authorized public accountant.', 'Panama', 'climate', 'in_force', '2001-01-01'::date, 'Panama', 'https://www.carrotsandsticks.org/policies/140_9', ARRAY['regulations', 'mandatory', 'disclosure', 'sdg9', 'panama']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7b509387-4c78-55da-b613-84dbf89960de', 'Peru National Action Plan on Business and Human Rights', 'National Action Plan on Business and Human Rights (NAP) 2021-2025', 'The National Action Plan on Business and Human Rights (NAP) 2021-2025 is Peru’s first policy framework addressing the intersection of business activities and human rights. Developed under the leadership of the Ministry of Justice and Human Rights, the plan aligns with international guidelines such as:

The United Nations Guiding Principles on Business and Human Rights (UNGPs)
The OECD Guidelines for Multinational Enterprises
The ILO Tripartite Declaration of Principles concerning Multinational Enterprises and Social Policy
The NAP aims to:

Ensure business respect for human rights, particularly for vulnerable populations.
Establish due diligence mechanisms for companies to prevent human rights violations.
Strengthen transparency, corporate responsibility, and environmental protections in business activities.
Provide judicial and extrajudicial remedies for individuals affected by corporate misconduct.
Promote multi-stakeholder dialogue between businesses, civil society, indigenous groups, and the government.
The policy includes five strategic guidelines and 13 objectives, with 97 actions and 150 indicators, involving 21 public entities alongside private sector and civil society actors.', 'The National Action Plan on Business and Human Rights (NAP) 2021-2025 is Peru’s first policy framework addressing the intersection of business activities and human rights. Developed under the leadership of the Ministry of Justice and Human Rights, the plan aligns with international guidelines such as:

The United Nations Guiding Principles on Business and Human Rights (UNGPs)
The OECD Guidelines for Multinational Enterprises
The ILO Tripartite Declaration of Principles concerning Multinational Enterprises and Social Policy
The NAP aims to:

Ensure business respect for human rights, particularly for vulnerable populations.
Establish due diligence mechanisms for companies to prevent human rights violations.
Strengthen transparency, corporate responsibility, and environmental protections in business activities.
Provide judicial and extrajudicial remedies for individuals affected by corporate misconduct.
Promote multi-stakeholder dialogue between businesses, civil society, indigenous groups, and the government.
The policy includes five strategic guidelines and 13 objectives, with 97 actions and 150 indicators, involving 21 public entities alongside private sector and civil society actors.', 'The National Action Plan on Business and Human Rights (NAP) 2021-2025 is Peru’s first policy framework addressing the intersection of business activities and human rights. Developed under the leadership of the Ministry of Justice and Human Rights, the plan aligns with international guidelines such as:

